namespace sv_5330d59d91b449ab9515d9e0c100f2c2.Client.Services;

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public record StatusUpdate(
    string Status,
    string Location,
    DateTimeOffset Timestamp);

namespace sv_5330d59d91b449ab9515d9e0c100f2c2.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;

namespace sv_5330d59d91b449ab9515d9e0c100f2c2.Client.Services;

/// <summary>
/// Client-side implementation that calls the server API over HTTP.
/// Used when the component runs in WebAssembly.
/// </summary>
public sealed class HttpShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_5330d59d91b449ab9515d9e0c100f2c2.Client.Services;

namespace sv_5330d59d91b449ab9515d9e0c100f2c2.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails(
            TrackingNumber: "PKG-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 12, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "New York, NY", new DateTimeOffset(2026, 7, 5, 10, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Picked Up", "New York, NY", new DateTimeOffset(2026, 7, 6, 8, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Chicago, IL", new DateTimeOffset(2026, 7, 8, 14, 15, 0, TimeSpan.Zero)),
            ]),
        ["PKG-002"] = new ShipmentDetails(
            TrackingNumber: "PKG-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Seattle, WA", new DateTimeOffset(2026, 7, 3, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Shipped", "Seattle, WA", new DateTimeOffset(2026, 7, 4, 11, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Portland, OR", new DateTimeOffset(2026, 7, 5, 16, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for Delivery", "San Francisco, CA", new DateTimeOffset(2026, 7, 7, 7, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 7, 7, 11, 45, 0, TimeSpan.Zero)),
            ]),
        ["PKG-003"] = new ShipmentDetails(
            TrackingNumber: "PKG-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 15, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate("Order Placed", "Dallas, TX", new DateTimeOffset(2026, 7, 9, 8, 0, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

