+        catch (TaskCanceledException ex) when (!_cts.Token.IsCancellationRequested)
+        {
+            // HttpClient throws TaskCanceledException on timeout when the token wasn't ours
+            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "The request timed out. Please try again.";
+        }
